UPDATE companies SET description='Kamuela Hardwoods operates from Waimea on the island of Hawaii, where it runs a sawmill dedicated to reclaiming urban and felled trees. The company was formed as a partnership between an arborist and a woodworker, with co‑owners Alex Woodbury and Joshua Greenspan (an ISA‑certified arborist) the operation.

The mill processes over 30 Hawaiian and exotic hardwood species — including koa, monkeypod, mango, Norfolk pine, lychee, eucalyptus, and ohia — into live‑edge slabs, kiln‑dried lumber, and bowl blanks. Logs are sawn on site, dried in a kiln to ensure stability, and every by‑product is repurposed: offcuts become utility lumber, sawdust turns to mulch, and slash is used for garden materials. The facility runs on locally produced bio‑diesel and follows a strict recycling program. A team of eight handles milling, woodworking, sales, and marketing, shipping products across Hawaii, the continental U.S., and internationally.

The lumber serves furniture makers, woodworkers, instrument builders, artisans, cabinetmakers, and builders seeking distinctive Hawaiian woods for custom projects, countertops, flooring, and musical instruments.

The founders frame the business as a response to waste: “We are trying to do something different, we don’t want to unnecessarily remove a tree for any reason,” says Woodbury. Greenspan adds, “It’s unfortunate when a tree has to come down, but in a sense, we’re giving it a new life.” The zero‑waste model and bio‑diesel power underscore a mission to salvage timber that would otherwise be burned or landfilled.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Urban timber salvage", "Sawmilling", "Kiln drying", "Live\u2011edge slab production", "Bowl blank production", "Custom milling", "Zero\u2011waste by\u2011product utilization", "Bio\u2011diesel powered operations", "Domestic and international shipping"], "industries": ["Furniture making", "Woodworking", "Instrument building", "Artisan crafts", "Cabinetry", "Countertop fabrication", "Flooring", "Construction"], "materials": ["Koa", "Monkeypod", "Mango", "Norfolk Pine", "Lychee", "Eucalyptus Robusta", "Acacia Koa", "Lehua Ohia", "Eucalyptus Saligna", "Toon", "Podocarpus", "Silk Oak", "Blue Gum", "Red Gum", "Australian Blackwood", "Citrus Wood", "Keawe"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Urban timber salvage from felled and urban trees", "Zero\u2011waste processing (all by\u2011products repurposed)", "Kiln\u2011dried lumber for dimensional stability", "Over 30 Hawaiian and exotic hardwood species available", "Equipment powered by locally produced bio\u2011diesel"], "facts_used": ["Location: Waimea, Hawaii -> db", "Founded as partnership between arborist and woodworker -> /about-us", "Co-owners: Alex Woodbury and Joshua Greenspan -> /about-us, /", "Joshua Greenspan is ISA Certified Arborist -> /about-us", "Over 30 Hawaiian and exotic hardwood species -> /", "Species list: koa, monkeypod, mango, Norfolk pine, lychee, eucalyptus, ohia, etc. -> /, /about-us", "Products: live-edge slabs, kiln-dried lumber, bowl blanks -> /", "Zero-waste operation: byproducts repurposed -> /, /about-us", "Equipment run on locally produced bio-diesel -> /about-us", "Strict recycling program -> /about-us", "Team of eight listed -> /about-us", "Ships across Hawaii, U.S., internationally -> /", "Serves furniture makers, woodworkers, instrument builders, artisans -> /", "Founder quotes on mission -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Kamuela Hardwoods is an urban timber salvage company, formed by a partnership between an arborist and a woodworker.", "founded_year": "", "employee_count": "8", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='kamuela-hardwoods' AND approved AND profile IS NULL;
UPDATE companies SET description='Kanson Electronics Inc operates from a 30,000-square-foot manufacturing and technical center in Hohenwald, Tennessee. The company''s ISSC line of timers, sensors, and counters has been produced in the United States since 1963. Kanson was woman-owned from 1979 to 2013 and is now veteran-owned.

The facility produces a range of industrial timing and sensing devices, including DIN-rail mount timers with customer-specified voltages, on-delay and true off-delay functions, and sensors with impermeable resin-filled casings. In addition to its own product line, Kanson provides contract manufacturing for electrical and electro-mechanical subassemblies and systems. A sister division, Modor Plastics, molds thermoplastics and thermosets on the same campus. Processes include screen printing, powder coating, encapsulation, and 100 percent testing and cycling of every unit before shipment.

The company''s timers and sensors are used in applications requiring accurate timing control, voltage isolation, and zero-maintenance operation, with many units remaining in service for decades.

Kanson emphasizes its all-U.S. production, centralized location for fast national shipping, and a quality regimen that tests every product before it leaves the plant. The company states that making the customer''s life easier is the reason it does business.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Screen printing", "Powder coating", "Electrical subassembly", "Electro-mechanical subassembly", "Systems assembly", "Thermoplastic molding", "Thermoset molding", "Encapsulation", "Resin filling", "100% testing and cycling", "Quality control", "Contract manufacturing"], "industries": ["Industrial automation", "Electrical equipment"], "materials": ["Thermoplastics", "Thermosets", "Resin"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["100% Made in the USA", "100% of products tested, cycled, and quality-checked before shipping", "30,000 sq ft manufacturing and technical center in Hohenwald, TN", "Veteran-owned and formerly woman-owned (1979\u20132013)", "Central U.S. location for fast shipping nationwide"], "facts_used": ["Founded 1963 -> db", "Headquarters Hohenwald, Tennessee -> db", "Veteran-owned -> /about", "Woman-owned from 1979 to 2013 -> /about", "30,000 sq ft manufacturing and technical center -> /about", "ISSC timers and sensors manufactured since 1963 -> /about, /", "Screen printing & powder coating available -> /, /about", "Contract manufacturing for electrical and electro-mechanical subassembly and systems -> /about", "Modor Plastics division for thermoplastics and thermosets -> /about", "100% Made in USA -> /, /about", "100% of products tested, cycled, quality-checked -> /, /about", "Central U.S. location for fast shipping -> /about", "Customers from small businesses to Fortune 200s -> /about", "Industrial timers with customer-specified voltages -> /", "Industrial sensors with resin-filled casings -> /", "Encapsulated circuitry -> /", "Powder coated enclosures -> /", "Models 1514, 1510, 1310 -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Manufacturing world-class ISSC timers, sensors, and counters in the USA since 1963.", "founded_year": "1963", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Veteran-owned", "Woman-owned"]}'::jsonb, updated_at=now() WHERE slug='kanson-electronics-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Kase Custom operates from Mesa, Arizona, where it was founded in 2014. The company began with a single table and a belief that craftsmanship and connection matter, growing into a certified B Corporation that handcrafts reclaimed wood furniture to order.

The Arizona shop produces custom tables — bar height, counter height, dining height, and coffee tables — built from reclaimed wood. Each piece is made to the customer''s exact dimensions and finish preferences, with a complimentary design service to assist with sizing. The company reports more than 5,500 orders delivered over 12-plus years, with a current build time of four to six weeks.

Kase Custom serves both hospitality and residential markets. Its furniture appears in international hotel brands and local coffee shops, where high-top bar tables are designed for daily commercial use. The same durability is offered for home kitchens, dining rooms, and gathering spaces.

The company positions its work as "slow furniture" — pieces built to last decades rather than seasons. Its B Corp certification and a 4.9-star rating across more than 800 reviews reflect a focus on responsible manufacturing and customer satisfaction.', certifications=ARRAY['B Corporation']::text[], profile='{"capabilities": ["Custom furniture design", "Handcrafted wood fabrication", "Reclaimed wood sourcing and processing", "Custom dimensions and finishes", "Complimentary design consultation", "Packaging and shipping"], "industries": ["Hospitality", "Residential", "Commercial"], "materials": ["Reclaimed wood"], "equipment": [], "volume": "", "lead_time": "4-6 weeks", "tolerances": "", "built_on": ["Custom dimensions for any space", "Handcrafted from reclaimed wood in Arizona", "Complimentary design consultation", "B Corp certified", "4-6 week lead time"], "facts_used": ["Founded 2014 in Mesa, Arizona -> db", "Certified B Corporation -> /", "5,500+ orders delivered -> /", "4.9 stars across 800+ reviews -> /", "Current build time 4-6 weeks -> /", "Serves hospitality (hotels, coffee shops) and residential -> /", "Custom made-to-order reclaimed wood furniture -> /", "Complimentary design service -> /", "Handcrafted in Arizona shop -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Handcrafted Reclaimed Wood Furniture, Handcrafted in the USA", "founded_year": "2014", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='kase-custom-custom-wood-furniture' AND approved AND profile IS NULL;
UPDATE companies SET description='Kayem Foods traces its roots to 1909 when Kazimierz Monkiewicz opened a small butcher shop in Chelsea, Massachusetts. Now in its fifth generation, the company remains family-owned and operated, with headquarters in Woburn, Massachusetts, while continuing to manufacture its products at its original Chelsea facility.

The company produces more than 200 items across ten brands, including frankfurters made from 100% pork and beef, pork and chicken sausages, bacon, slow-cooked smoked meats, deli selections such as ham and Italian specialties, and breakfast links and patties.

Its products reach home cooks, grill enthusiasts, chefs, restaurants, retailers, and major stadiums and ballparks across the United States.

